# Builds maester.dev (Astro + Starlight) and checks that every URL of the old site still resolves. On a pull
# request it only builds; on main, daily and on request it also deploys the build to Cloudflare Pages.
#
# The site's generated data is not kept in git: the build exports the test catalog and the command reference from
# the module source, credits contributors from the git history and looks up sponsors on GitHub
# (website/scripts/prepare-data.mjs). So a merge needs no follow-up pull request, and the daily run picks up new
# sponsors.
#
# Deploying needs the CLOUDFLARE_API_TOKEN secret (a token with Cloudflare Pages: Edit) and the
# CLOUDFLARE_ACCOUNT_ID secret in the maester.dev environment. The Cloudflare Pages project, which the
# CLOUDFLARE_PAGES_PROJECT variable can name (default: maester), must not also build from git.
name: "\U0001F3D7️ Build Website"

on:
  workflow_call:
    inputs:
      node_version:
        description: "Node.js version to use."
        required: false
        default: "24.x"
        type: string
      working_directory:
        description: "Path to the directory containing package.json (relative to the repository root)."
        required: false
        default: "website"
        type: string
  workflow_dispatch:
  schedule:
    - cron: "17 3 * * *" # Daily, 03:17 UTC: new sponsors
  push:
    branches: ["main"]
  pull_request:
    branches: ["main"]
    # Only what the site is built from: the exported commands' help (the manifest lists them), the tests, the
    # engine and the assets that read the tests into the catalog (taxonomy, schema, legacy tags), and the docs.
    paths:
      - "README.md"
      - "build/Update-CommandReference.ps1"
      - "build/docs/**"
      - "build/eidsca/*.json"
      - "powershell/Maester.psd1"
      - "powershell/assets/**"
      - "powershell/internal/engine/**"
      - "powershell/public/**"
      - "tests/**"
      - "website/**"
      - ".github/workflows/build-website.yaml"

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

permissions: {}

jobs:
  build:
    name: "Build website \U0001F3D7️"
    runs-on: ubuntu-latest
    permissions:
      contents: read
    defaults:
      run:
        working-directory: ${{ inputs.working_directory || 'website' }}

    steps:
      # On main, the maester-bot app's token: it may read whether each contributor has a GitHub Sponsors listing
      # and who sponsors the maintainers. A pull request build uses the repository's token, which may not, and
      # shows the sponsors of the last deploy.
      - name: Generate maester-bot app token
        id: app-token
        if: github.event_name != 'pull_request'
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3.3.0
        with:
          app-id: ${{ secrets.MAESTER_BOT_APP_ID }}
          private-key: ${{ secrets.MAESTER_BOT_PRIVATE_KEY }}
          # Read only: the build reads public profiles, sponsorships and the repository's contributors.
          permission-contents: read

      - name: ⬇️ Checkout repository
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          # Full history so contributor profiles get display names and first-contribution dates from git.
          fetch-depth: 0
          persist-credentials: false

      - name: ⚙️ Set up Node.js ${{ inputs.node_version || '24.x' }}
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: ${{ inputs.node_version || '24.x' }}
          cache: "npm"
          cache-dependency-path: ${{ inputs.working_directory || 'website' }}/package-lock.json

      - name: "\U0001F4E6 Install dependencies"
        run: npm ci

      # The PowerShell modules the build needs, by the pinned versions in the files that pin them. On a hit the
      # PowerShell Gallery is not contacted at all, which is the point: the Gallery handing a runner a source
      # location it cannot use has failed this job with an error four steps removed from the cause.
      - name: Restore the PowerShell modules
        uses: actions/cache@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        with:
          path: ~/.local/share/powershell/Modules
          key: pwsh-modules-${{ runner.os }}-${{ hashFiles('build/Update-CommandReference.ps1', '.github/workflows/build-website.yaml') }}
          restore-keys: pwsh-modules-${{ runner.os }}-

      # The test catalog export imports the source module, which needs this module. Retried, because a failed
      # download here is a Gallery problem rather than a problem with the change being built.
      - name: Install Microsoft.Graph.Authentication
        shell: pwsh
        run: |
          $ErrorActionPreference = 'Stop'
          $available = { [bool](Get-Module Microsoft.Graph.Authentication -ListAvailable |
                  Where-Object { $_.Version -ge [version]'2.27.0' }) }
          if (& $available) { 'Already available.'; exit 0 }
          foreach ($attempt in 1..3) {
              try {
                  Install-Module Microsoft.Graph.Authentication -MinimumVersion 2.27.0 -Scope CurrentUser -Repository PSGallery -Force
              } catch {
                  Write-Host "::warning::Attempt $attempt of 3 failed: $($_.Exception.Message)"
              }
              if (& $available) { exit 0 }
              if ($attempt -lt 3) { Start-Sleep -Seconds (5 * $attempt) }
          }
          throw 'Could not install Microsoft.Graph.Authentication from the PowerShell Gallery after 3 attempts.'

      # The Open Graph cards rendered by earlier builds, by their hash (scripts/og-images.mjs): a build renders only
      # the cards of the pages that changed.
      - name: Restore the Open Graph cards
        uses: actions/cache@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        with:
          path: ${{ inputs.working_directory || 'website' }}/.cache/og
          key: og-cards-${{ github.run_id }}
          restore-keys: og-cards-

      # npm run build first generates the site's data (scripts/prepare-data.mjs), renders the Open Graph cards, then
      # checks every URL in website/src/data/url-contract.txt against the output.
      - name: "\U0001F3D7️ Build website"
        env:
          GH_TOKEN: ${{ steps.app-token.outputs.token || github.token }}
        run: npm run build

      # The README's Sponsors section is written from website/sponsors/featured.yml.
      - name: Check the README's Sponsors section
        if: github.event_name == 'pull_request'
        run: |
          node scripts/sponsors.mjs --readme
          git diff --exit-code -- ../README.md || { echo "::error file=README.md::The Sponsors section is out of date. Run: cd website && node scripts/sponsors.mjs --readme"; exit 1; }

      - name: Upload the site
        if: github.event_name != 'pull_request'
        uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        with:
          name: website
          path: ${{ inputs.working_directory || 'website' }}/dist
          if-no-files-found: error
          retention-days: 7

  deploy:
    name: Deploy to maester.dev
    needs: build
    if: github.event_name != 'pull_request' && github.ref == 'refs/heads/main' && github.repository == 'maester365/maester'
    runs-on: ubuntu-latest
    permissions:
      contents: read
    environment:
      name: maester.dev
      url: https://maester.dev

    steps:
      - name: Download the site
        uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
        with:
          name: website
          path: dist

      - name: Set up Node.js
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 24.x

      - name: Deploy to Cloudflare Pages
        env:
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          PROJECT: ${{ vars.CLOUDFLARE_PAGES_PROJECT || 'maester' }}
          COMMIT: ${{ github.sha }}
        run: npx --yes wrangler@4.151.2 pages deploy dist --project-name "$PROJECT" --branch main --commit-hash "$COMMIT" --commit-dirty=true
// Build-time data of the test catalog explorer: src/data/explorer.json, written by scripts/catalog-explorer.mjs.
import explorer from '../../data/explorer.json';
import { productIcon, productInitials, featureIcon } from '../../lib/report-icons.mjs';
import { previewLabel } from '../../lib/versions.mjs';

export type Check = (typeof explorer.tests)[number] & { pillar?: string[]; category?: string; also?: string[]; testId?: string };
export const data = explorer;
export const checks = explorer.tests as Check[];
export const severityOrder = ['Critical', 'High', 'Medium', 'Low', 'Info'];
export const ratingOrder = ['Low', 'Medium', 'High'];
export { previewLabel, productIcon, productInitials, featureIcon };

export const productName = (key: string) => explorer.products.find((p) => p.key === key)?.name ?? key;
export const packOf = (code: string) => explorer.packs.find((p) => p.code === code);
export const frameworkOf = (key: string) => explorer.frameworks.find((f) => f.key === key);
export const checkUrl = (id: string) => `/docs/tests/${id}`;

// The suites of the nav, by their key in the URL of their page (/docs/tests/<key>).
export const suiteInfo: Record<string, { name: string; slug: string }> = {
	Maester: { name: 'Maester', slug: 'maester' },
	CIS: { name: 'CIS', slug: 'cis' },
	CISA: { name: 'CISA SCuBA', slug: 'cisa' },
	ASD: { name: 'ASD Essential Eight', slug: 'asd' },
	EIDSCA: { name: 'Entra ID SCA (EIDSCA)', slug: 'eidsca' },
	ORCA: { name: 'ORCA', slug: 'orca' },
	AD: { name: 'Active Directory', slug: 'ad' },
	XSPM: { name: 'Exposure management (XSPM)', slug: '' },
};

// The channel of a check for the filter: new in the preview, runs only with -IncludePreview, or both.
export const channelOf = (t: Check) => [t.previewOnly && !t.pack ? 'new' : '', t.previewCheck ? 'preview' : ''].filter(Boolean).join(' ');
// The text the catalog's search looks in.
export const searchText = (t: Check) => `${t.id} ${t.title} ${t.productName} ${t.featureName} ${t.areaName} ${t.mitre.join(' ')} ${t.category ?? ''}`.toLowerCase();

// The suites a suite's page lists: XSPM has no page, and its MT checks have their pages under Maester's.
export const suiteMembers = (suite: string) => (suite === 'Maester' ? ['Maester', 'XSPM'] : [suite]);

const pillarNames = new Map([['SecOps', 'Security operations']]);
export const pillarName = (p: string) => pillarNames.get(p) ?? p;

export function severityMix(list: Check[]) {
	return severityOrder.map((s) => ({ key: s, count: list.filter((t) => t.severity === s).length })).filter((s) => s.count);
}

export const plural = (n: number, word: string) => `${n.toLocaleString('en-US')} ${word}${n === 1 ? '' : 's'}`;

// Each framework of the nav, in the nav's order (NIST first): its short code, the suite that runs it and how its requirements are grouped. A
// framework whose file lists only the requirements Maester checks (CIS GitHub, ISM) has no coverage figure.
