function readJson<T>(relative: string, fallback: T): T {
  const file = path.join(dataDir, relative);
  if (!fs.existsSync(file)) return fallback;
  // The indexer writes UTF-8 without a BOM; strip one anyway.
  return JSON.parse(fs.readFileSync(file, 'utf8').replace(/^﻿/, '')) as T;
}

const asArray = <T>(value: T | T[] | null | undefined): T[] => (value == null ? [] : Array.isArray(value) ? value : [value]);

export function getIndex(): { GeneratedAt?: string; Packs: IndexRow[] } {
  const index = readJson<{ GeneratedAt?: string; Packs: IndexRow[] }>('index.json', { Packs: [] });
  index.Packs = asArray(index.Packs).map((p) => ({ ...p, Badges: asArray(p.Badges), Services: asArray(p.Services), Connectors: asArray(p.Connectors), Products: asArray(p.Products), Pillars: asArray(p.Pillars) }));
  return index;
}

export function getListing(row: IndexRow): Listing {
  const l = readJson<Listing>(row.Path, null as unknown as Listing);
  return {
    ...l,
    Connectors: asArray(l.Connectors).map((c) => ({ ...c, Settings: asArray(c.Settings) })),
    Tests: asArray(l.Tests).map((t) => ({ ...t, Service: asArray(t.Service), Product: asArray(t.Product), RelatedProduct: asArray(t.RelatedProduct), Pillar: asArray(t.Pillar) })),
    Products: asArray(l.Products),
    Pillars: asArray(l.Pillars),
    Screenshots: asArray(l.Screenshots),
    Guide: l.Guide ? normaliseGuide(l.Guide) : null,
    Findings: asArray(l.Findings),
    Binaries: asArray(l.Binaries),
    Warnings: asArray(l.Warnings),
    Badges: asArray(l.Badges),
    Reasons: asArray(l.Reasons),
    Notices: asArray(l.Notices),
  };
}

function normaliseGuide(g: Guide): Guide {
  const section = (x: GuideSection | null | undefined) => (x ? { ...x, Steps: asArray(x.Steps), Notes: asArray(x.Notes) } : null);
  return {
    ...g,
    Prerequisites: asArray(g.Prerequisites),
    Connect: section(g.Connect),
    Run: g.Run ? { ...g.Run, Commands: asArray(g.Run.Commands), Options: asArray(g.Run.Options), Notes: asArray(g.Run.Notes) } : null,
    AppOnly: g.AppOnly ? { ...g.AppOnly, OtherRoles: asArray(g.AppOnly.OtherRoles) } : null,
    Links: asArray(g.Links),
  };
}

