429		const show = (next: number, forward = next > current) => {
430			if (next === current) return;
431			const from = panels[current];
432			const to = panels[next];
433			// The incoming page starts on the side it comes from, without animating there.
434			for (const p of panels) p.classList.remove('is-moving');
435			to.classList.remove('is-before', 'is-after');
436			to.classList.add(forward ? 'is-after' : 'is-before');
