461				if (!still) caption.animate([{ opacity: 0, transform: 'translateY(4px)' }, { opacity: 1, transform: 'none' }], { duration: 400, easing: 'ease-out' });
462			}
463			if (open) open.href = `${demo}#${tabs[next].dataset.hash}`;
464			if (next === liveIndex) loadLive();
465		};
