472		tabs.forEach((tab, i) => {
473			tab.addEventListener('click', () => choose(i));
474			tab.addEventListener('keydown', (event) => {
475				const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0;
476				const index = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : step ? (current + step + tabs.length) % tabs.length : -1;
477				if (index < 0) return;
478				event.preventDefault();
479				choose(index);
480				tabs[index].focus();
481			});
