504		// Full screen: the frame fills the screen, whichever view or the live report it shows. Where a browser can't
505		// (iPhone Safari), the live report opens in a tab of its own instead.
506		// While the live report shows, "open in a new tab" opens the page the reader is on.
507		const liveHref = () => {
