---
// Pricing: Maester itself is free wherever it runs; Maester Cloud is the paid option. The Cloud plans and prices live
// on maester.cloud/pricing, so this page names only the starting price and links there.
import SiteLayout from '../layouts/SiteLayout.astro';

const free = [
	{
		label: 'Your desktop',
		title: 'Run it on your own machine.',
		body: 'Install the module, connect to your tenant and get the full report in one run. Windows, macOS and Linux.',
		points: ['Every check, pack and the HTML report', 'Your data never leaves your machine', 'PowerShell 7.4 or later'],
		cta: { label: 'Install Maester', href: '/docs/installation' },
	},
	{
		label: 'GitHub Actions',
		title: 'Run it every day in GitHub.',
		body: 'A workflow in your own repository runs Maester on a schedule and keeps each report.',
		points: ['Daily runs on a schedule you set', 'Reports kept with each run', 'Email or Teams alerts when a check fails'],
		cta: { label: 'Set up GitHub Actions', href: '/docs/monitoring/github' },
	},
	{
		label: 'Automation',
		title: 'Run it in the pipeline you already have.',
		body: 'Azure Automation, Azure DevOps, Azure Container Apps, GitLab or Bitbucket: Maester runs wherever PowerShell does.',
		points: ['Templates for Azure Automation and Azure DevOps', 'Bicep and Terraform deployments', 'Your schedule, your storage'],
		cta: { label: 'See the automation guides', href: '/docs/monitoring' },
	},
];
---

<SiteLayout
	title="Pricing"
	description="Maester is free on your desktop, in GitHub Actions and in your own automation. Maester Cloud runs it securely in Azure with simplified deployment and run history, from $99 a month."
	wide
>
	<header class="head">
		<p class="eyebrow">Pricing</p>
		<h1>Maester is free. Wherever you run it.</h1>
		<p class="sub">
			Every check, every pack and the full report are free and open source. Run Maester on your desktop, in GitHub Actions or
			in your own automation. When you want it run for you, there's Maester Cloud.
		</p>
	</header>

	<section class="plans" aria-label="Ways to run Maester">
		{
			free.map((p) => (
				<article class="plan">
					<p class="eyebrow">{p.label}</p>
					<p class="price">
						<strong>Free</strong>
						<span>forever</span>
					</p>
					<h2>{p.title}</h2>
					<p class="body">{p.body}</p>
					<ul>
						{p.points.map((point) => <li>{point}</li>)}
					</ul>
					<a class="site-btn site-btn--ghost" href={p.cta.href}>
						{p.cta.label}
					</a>
				</article>
			))
		}
		<article class="plan plan--cloud">
			<p class="eyebrow">Maester Cloud</p>
			<p class="price">
				<span>From</span>
				<strong>$99</strong>
				<span>/ month</span>
			</p>
			<h2>Run it securely in Azure.</h2>
			<p class="body">Maester Cloud does the running for you, with nothing to script or schedule.</p>
			<ul>
				<li>Runs securely in Azure</li>
				<li>Simplified deployment</li>
				<li>Run history for every tenant</li>
				<li>Drift and alerts across tenants</li>
				<li>Your subscription keeps Maester free</li>
			</ul>
			<a class="site-btn site-btn--primary" href="https://maester.cloud/pricing">See Maester Cloud pricing</a>
		</article>
	</section>

	<p class="note">
		The checks are the same in every option: Maester Cloud runs the same open-source engine and checks. Maester Cloud
		subscriptions fund the maintainers who build them. <a href="/sponsor">Other ways to support Maester</a>
	</p>
</SiteLayout>

<style>
	.head {
		text-align: center;
		max-width: 46rem;
