	}
	.plan {
		display: flex;
		flex-direction: column;
		gap: 0.75rem;
		border: 1px solid var(--mt-line);
		border-radius: 20px;
		background: var(--mt-surface);
		padding: 1.5rem;
	}
	.plan h2 {
		font-size: 1.2rem;
		font-weight: 600;
		letter-spacing: -0.01em;
		line-height: 1.25;
		margin: 0;
	}
	.price {
		display: flex;
		align-items: baseline;
		gap: 0.35rem;
		margin: 0.25rem 0 0;
		color: var(--sl-color-gray-3);
		font-size: 0.9rem;
	}
	.price strong {
		font-size: 2.25rem;
		font-weight: 600;
		letter-spacing: -0.02em;
		color: var(--sl-color-white);
	}
	.body {
		color: var(--sl-color-gray-2);
		font-size: 0.95rem;
		line-height: 1.5;
		margin: 0;
	}
	ul {
		list-style: none;
		padding: 0;
		margin: 0.25rem 0 0.5rem;
		display: flex;
		flex-direction: column;
		gap: 0.45rem;
		font-size: 0.9rem;
	}
	li {
