		text-align: center;
	}
	/* Maester Cloud: the dark card, whatever the page's theme. */
	.plan--cloud {
		--sl-color-white: #f5f5f7;
		--sl-color-gray-2: #a1a1a6;
		--sl-color-gray-3: #86868b;
		color: #f5f5f7;
		border-color: #3d2326;
		background: radial-gradient(120% 80% at 50% 120%, #4a1418 0%, #161617 65%);
	}
	.plan--cloud .eyebrow {
		color: #ff6b6f;
	}
	.note {
		max-width: 46rem;
		margin: 2.5rem auto 1rem;
		text-align: center;
		color: var(--sl-color-gray-3);
		font-size: 0.9rem;
		line-height: 1.6;
	}
	@media (max-width: 64rem) {
		.plans {
			grid-template-columns: repeat(2, minmax(0, 1fr));
		}
	}
	@media (max-width: 40rem) {
		.plans {
			grid-template-columns: minmax(0, 1fr);
		}
	}
</style>

